SET NOCOUNT ON;SET XACT_ABORT ON;EXEC fwk.USP_WaitForSignal '$(DemoId)','$(RunToken)','WAITER_COMPLETED',15000;UPDATE lab.Evidence SET InstanceAfterMs=COALESCE((SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_type LIKE 'LCK_M_%'),0) WHERE EvidenceId=1;IF NOT EXISTS(SELECT 1 FROM lab.Evidence WHERE TaskWaitType LIKE 'LCK_M_%' AND RequestWaitType LIKE 'LCK_M_%' AND WaiterSessionId IS NOT NULL AND BlockerSessionId IS NOT NULL) THROW 51006,'FAIL_RESULT_CONTRACT: Task-/Request-Scope fehlt.',1;SELECT *,InstanceAfterMs-InstanceBaselineMs InstanceDeltaMs FROM lab.Evidence;PRINT 'SQLPERF_SUMMARY|PASS|OK';
